<?php
require __DIR__ . '/src/bootstrap.php';
?>
<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>EXPEDIG - Expedientes Digitales</title>
<style>
:root{--navy:#06264b;--blue:#0d5bd7;--line:#dbe3ee;--bg:#f4f7fb;--text:#10233f;--muted:#66758a;--green:#169b62}*{box-sizing:border-box}body{margin:0;font-family:Inter,Segoe UI,Arial,sans-serif;background:var(--bg);color:var(--text)}header{height:76px;background:var(--navy);color:#fff;display:flex;align-items:center;padding:0 24px;gap:24px;position:sticky;top:0;z-index:5}.brand{font-size:21px;font-weight:800;min-width:260px}.brand small{display:block;font-size:12px;font-weight:500}.search{flex:1;max-width:850px;position:relative}.search input{width:100%;height:46px;border-radius:9px;border:0;padding:0 16px;font-size:16px}.results{position:absolute;top:52px;left:0;right:0;background:#fff;color:var(--text);border:1px solid var(--line);border-radius:9px;box-shadow:0 12px 30px #001b3a22;display:none;overflow:hidden}.result{padding:12px 14px;border-bottom:1px solid #edf1f6;cursor:pointer}.result:hover{background:#f1f6ff}.layout{display:grid;grid-template-columns:225px 1fr;min-height:calc(100vh - 76px)}aside{background:linear-gradient(#06315f,#05264a);color:white;padding:18px 10px}.nav{padding:13px 14px;border-radius:8px;margin-bottom:6px}.nav.active{background:var(--blue)}main{padding:22px}.empty{background:#fff;border:1px solid var(--line);border-radius:13px;min-height:560px;display:grid;place-items:center;text-align:center}.empty h2{margin-bottom:6px}.muted{color:var(--muted)}#record{display:none}.profile{background:#fff;border:1px solid var(--line);border-radius:13px;padding:18px 20px;display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.profile h2{margin:0 0 7px}.badge{display:inline-block;background:#dff5e9;color:#0b7a4a;border-radius:20px;padding:5px 10px;font-size:12px;font-weight:700}.button{border:1px solid var(--line);background:#fff;color:var(--text);padding:10px 14px;border-radius:8px;font-weight:600;cursor:pointer}.button.primary{background:var(--blue);color:#fff;border-color:var(--blue)}.grid{display:grid;grid-template-columns:285px minmax(430px,1fr) minmax(360px,46%);gap:14px}.card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:16px;min-width:0}.card h3{font-size:13px;margin:0 0 14px;color:#153c71}.info-row{display:grid;grid-template-columns:105px 1fr;gap:8px;font-size:13px;margin:11px 0}.docs{border:1px solid var(--line);border-radius:8px;overflow:hidden}.docrow{display:grid;grid-template-columns:minmax(135px,1.2fr) 90px minmax(120px,1.4fr);gap:8px;padding:11px;border-bottom:1px solid #edf1f6;font-size:12px;align-items:center}.docrow:last-child{border-bottom:0}.doctype{color:#095bca;font-weight:700;cursor:pointer}.doctype:hover{text-decoration:underline}.preview{display:flex;flex-direction:column;min-height:610px}.preview-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px}.preview iframe{width:100%;flex:1;min-height:530px;border:1px solid var(--line);border-radius:8px;background:#eef2f6}.placeholder{flex:1;display:grid;place-items:center;text-align:center;border:2px dashed #dbe3ee;border-radius:8px;color:var(--muted);padding:25px}.modal{position:fixed;inset:0;background:#00182f88;display:none;align-items:center;justify-content:center;z-index:10}.modal.show{display:flex}.modal-box{background:#fff;width:min(560px,92vw);border-radius:12px;padding:20px}.field{margin:12px 0}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid var(--line);border-radius:7px}.actions{display:flex;gap:8px;justify-content:flex-end;margin-top:15px}@media(max-width:1100px){.grid{grid-template-columns:250px 1fr}.preview{grid-column:1/-1}.layout{grid-template-columns:190px 1fr}}@media(max-width:760px){header{height:auto;flex-wrap:wrap;padding:12px}.brand{min-width:0}.layout{display:block}aside{display:none}main{padding:10px}.grid{display:block}.card{margin-bottom:10px}.profile{align-items:flex-start;gap:10px;flex-direction:column}}
</style>
</head>
<body>
<header><div class="brand">EXPEDIG<small>EXPEDIENTES DIGITALES · SEGURO PRIVADO</small></div><div class="search"><input id="search" autocomplete="off" placeholder="Buscar por posición, cédula o nombre..."><div id="results" class="results"></div></div></header>
<div class="layout"><aside><div class="nav active">⌕ Buscar expediente</div><div class="nav">▣ Expedientes</div><div class="nav">▤ Digitalización</div><div class="nav">▥ Reportes</div><div class="nav">▦ Estadísticas</div></aside><main>
<section id="empty" class="empty"><div><div style="font-size:52px">📁</div><h2>Buscar expediente policial</h2><div class="muted">Escriba la posición, cédula, nombre o apellido del funcionario.</div></div></section>
<section id="record">
 <div class="profile"><div><h2 id="title"></h2><div id="direction" class="muted"></div><div style="margin-top:9px"><span class="badge" id="status"></span></div></div><button class="button primary" onclick="openUpload()">＋ Digitalizar documento</button></div>
 <div class="grid">
  <div class="card"><h3>RESUMEN DEL EXPEDIENTE</h3><div id="officerInfo"></div></div>
  <div class="card"><h3>DOCUMENTOS DIGITALIZADOS (<span id="docCount">0</span>)</h3><div class="docs" id="docs"></div></div>
  <div class="card preview"><div class="preview-head"><div><h3 style="margin-bottom:5px">VISTA PREVIA DEL DOCUMENTO</h3><strong id="previewName">Ningún documento seleccionado</strong></div><button id="closePreview" class="button" style="display:none" onclick="clearPreview()">×</button></div><div id="previewPlaceholder" class="placeholder">Presione el <b>tipo de documento</b> para ver aquí el PDF sin salir del expediente.</div><iframe id="viewer" title="Vista previa PDF" style="display:none"></iframe></div>
 </div>
</section>
</main></div>
<div id="uploadModal" class="modal"><div class="modal-box"><h2>Digitalizar documento</h2><form id="uploadForm"><input type="hidden" name="officer_id" id="uploadOfficer"><div class="field"><label>Tipo de documento</label><select name="document_type_id" id="documentType" required></select></div><div class="field"><label>Fecha del documento</label><input type="date" name="document_date"></div><div class="field"><label>Descripción / observaciones</label><textarea name="description" rows="3"></textarea></div><div class="field"><label>Archivo PDF</label><input type="file" name="file" accept="application/pdf,.pdf" required></div><div class="actions"><button type="button" class="button" onclick="closeUpload()">Cancelar</button><button class="button primary" type="submit">Guardar documento</button></div></form></div></div>
<script>
let currentOfficer=null, timer=null;
const $=s=>document.querySelector(s);
$('#search').addEventListener('input',e=>{clearTimeout(timer);timer=setTimeout(()=>search(e.target.value.trim()),220)});
async function search(q){const box=$('#results');if(!q){box.style.display='none';return}const r=await fetch('api.php?action=search&q='+encodeURIComponent(q));const rows=await r.json();box.innerHTML=rows.length?rows.map(x=>`<div class="result" data-id="${x.id}"><b>${esc(x.position)} · ${esc(x.rank_name||'')} ${esc(x.first_name)} ${esc(x.last_name)}</b><br><small>${esc(x.cedula||'Sin cédula')} · ${esc(x.direction||'Sin dependencia')}</small></div>`).join(''):'<div class="result">Sin resultados</div>';box.style.display='block';box.querySelectorAll('[data-id]').forEach(el=>el.onclick=()=>loadOfficer(el.dataset.id));}
async function loadOfficer(id){$('#results').style.display='none';const r=await fetch('api.php?action=officer&id='+id);const data=await r.json();if(!r.ok){alert(data.error||'Error');return}currentOfficer=data;const o=data.officer;$('#empty').style.display='none';$('#record').style.display='block';$('#title').textContent=`${o.position} - ${o.rank_name||''} ${o.first_name} ${o.last_name}`;$('#direction').textContent=o.direction||'Sin dependencia';$('#status').textContent=(o.status||'activo').toUpperCase();$('#officerInfo').innerHTML=info('Posición',o.position)+info('Cédula',o.cedula||'—')+info('Rango',o.rank_name||'—')+info('Nombre',o.first_name+' '+o.last_name)+info('Dirección / Zona',o.direction||'—')+info('Departamento',o.department||'—');$('#docCount').textContent=data.documents.length;$('#docs').innerHTML=data.documents.length?data.documents.map(d=>`<div class="docrow"><span class="doctype" onclick="preview(${d.id},'${attr(d.document_type)}')">${esc(d.document_type)}</span><span>${esc(d.document_date||'—')}</span><span>${esc(d.description||d.original_name)}</span></div>`).join(''):'<div style="padding:22px;text-align:center" class="muted">Todavía no hay documentos digitalizados.</div>';$('#documentType').innerHTML=data.document_types.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');$('#uploadOfficer').value=o.id;clearPreview();}
function preview(id,name){$('#previewName').textContent=name;$('#previewPlaceholder').style.display='none';$('#viewer').style.display='block';$('#viewer').src='api.php?action=document&id='+id+'#toolbar=1&navpanes=0';$('#closePreview').style.display='inline-block'}
function clearPreview(){$('#viewer').src='about:blank';$('#viewer').style.display='none';$('#previewPlaceholder').style.display='grid';$('#previewName').textContent='Ningún documento seleccionado';$('#closePreview').style.display='none'}
function openUpload(){if(!currentOfficer)return;$('#uploadModal').classList.add('show')}function closeUpload(){$('#uploadModal').classList.remove('show')}
$('#uploadForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;btn.textContent='Guardando...';try{const r=await fetch('api.php?action=upload',{method:'POST',body:new FormData(e.target)});const data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo guardar');closeUpload();e.target.reset();await loadOfficer(currentOfficer.officer.id);}catch(err){alert(err.message)}finally{btn.disabled=false;btn.textContent='Guardar documento'}});
function info(a,b){return `<div class="info-row"><b>${esc(a)}:</b><span>${esc(b)}</span></div>`}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function attr(v){return String(v??'').replace(/'/g,'&#039;')}
</script>
</body></html>
